(() => {
  const generated = new Map((window.FRIEND_AVATARS || []).map(avatar => [avatar.src, avatar]));
  const selector = '#friend-avatar,#gb-avatar-preview,#gb-preview-avatar,#gb-avatar-options img,#directory-list img,.forest-portrait';
  const materials = ['leaf', 'linen', 'cream', 'mist', 'blossom', 'kraft'];
  const labels = ['叶笺', '亚麻笺', '奶油信纸', '雾青笺', '花笺', '牛皮纸'];

  function mount(image) {
    if (!(image instanceof HTMLImageElement) || !image.matches(selector)) return;
    let frame = image.parentElement;
    if (!frame?.classList.contains('portrait-frame')) {
      frame = document.createElement('span');
      frame.className = 'portrait-frame';
      frame.dataset.portraitContext = image.id || (image.closest('#directory-list') ? 'directory' : image.closest('#gb-avatar-options') ? 'picker' : 'specimen');
      image.before(frame); frame.append(image);
    }
    frame.hidden = image.hidden;
    const avatar = generated.get(image.getAttribute('src'));
    if (avatar?.frame) {
      frame.dataset.portrait = avatar.id;
      frame.style.setProperty('--portrait-scale', avatar.frame.scale);
      frame.style.setProperty('--portrait-x', `${avatar.frame.x * 100}%`);
      frame.style.setProperty('--portrait-y', `${avatar.frame.y * 100}%`);
    } else {
      delete frame.dataset.portrait;
      ['--portrait-scale', '--portrait-x', '--portrait-y'].forEach(property => frame.style.removeProperty(property));
    }
  }

  function scan(root) {
    if (root instanceof HTMLImageElement) mount(root);
    root.querySelectorAll?.(selector).forEach(mount);
  }

  function setPaper(card, identity) {
    const hash = [...String(identity)].reduce((value, character) => (value * 31 + character.codePointAt(0)) >>> 0, 0);
    const index = hash % materials.length;
    card.dataset.paper = materials[index];
    card.dataset.paperName = labels[index];
    return materials[index];
  }

  const observer = new MutationObserver(records => {
    for (const record of records) {
      if (record.type === 'attributes') mount(record.target);
      else record.addedNodes.forEach(scan);
    }
  });
  observer.observe(document.body, { subtree: true, childList: true, attributes: true, attributeFilter: ['src', 'hidden'] });
  scan(document.body);
  window.friendPortraits = { mount, scan, setPaper, materials, labels, destroy: () => observer.disconnect() };
})();


